// STYLES
// =============================================
const S = {
  // Layout
  app: { display: "flex", height: "100vh", background: "#fff5f7", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif" },
  sidebar: { width: "220px", background: "#fff", borderRight: "1px solid #fce4ec", display: "flex", flexDirection: "column", padding: "24px 0", boxShadow: "2px 0 12px rgba(233,30,99,0.05)", flexShrink: 0 },
  main: { flex: 1, display: "flex", flexDirection: "column", overflow: "hidden" },
  content: { flex: 1, padding: "28px 32px", overflowY: "auto" },

  // Login screen
  loginWrap: { display: "flex", alignItems: "center", justifyContent: "center", height: "100vh", background: "linear-gradient(135deg, #fff5f7 0%, #fce4ec 100%)" },
  loginBox: { background: "#fff", borderRadius: "20px", padding: "48px 40px", width: "380px", boxShadow: "0 8px 40px rgba(233,30,99,0.12)", textAlign: "center" },
  loginTitle: { fontSize: "28px", fontWeight: "700", color: "#e91e63", marginBottom: "6px" },
  loginSub: { fontSize: "14px", color: "#aaa", marginBottom: "32px" },
  userGrid: { display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" },
  userCard: (selected) => ({
    padding: "16px 12px",
    borderRadius: "14px",
    border: `2px solid ${selected ? "#e91e63" : "#fce4ec"}`,
    background: selected ? "#fce4ec" : "#fff",
    cursor: "pointer",
    transition: "all 0.2s",
    textAlign: "center",
  }),
  avatar: (color, size = 44) => ({
    width: size, height: size,
    background: color,
    borderRadius: "50%",
    display: "flex", alignItems: "center", justifyContent: "center",
    color: "#fff", fontWeight: "700",
    fontSize: size > 36 ? "18px" : "14px",
    margin: "0 auto 8px",
  }),
  loginBtn: (disabled) => ({
    marginTop: "24px", width: "100%", padding: "14px",
    background: disabled ? "#fce4ec" : "#e91e63",
    color: disabled ? "#f48fb1" : "#fff",
    border: "none", borderRadius: "14px",
    fontSize: "15px", fontWeight: "600",
    cursor: disabled ? "not-allowed" : "pointer",
    transition: "all 0.2s",
  }),

  // Sidebar
  logo: { padding: "0 24px 24px", fontSize: "20px", fontWeight: "700", color: "#e91e63" },
  logoSub: { fontSize: "11px", color: "#f48fb1", fontWeight: "400", display: "block" },
  navItem: (active) => ({
    display: "flex", alignItems: "center", gap: "12px",
    padding: "12px 24px", cursor: "pointer",
    fontSize: "14px", fontWeight: active ? "600" : "400",
    color: active ? "#e91e63" : "#555",
    background: active ? "#fce4ec" : "transparent",
    borderLeft: active ? "3px solid #e91e63" : "3px solid transparent",
    transition: "all 0.2s",
  }),
  userPill: { margin: "auto 16px 8px", background: "#fce4ec", borderRadius: "12px", padding: "10px 12px", display: "flex", alignItems: "center", gap: "10px" },

  // Header
  header: { background: "#fff", borderBottom: "1px solid #fce4ec", padding: "16px 32px", display: "flex", alignItems: "center", justifyContent: "space-between" },
  headerTitle: { fontSize: "18px", fontWeight: "600", color: "#222" },
  badge: (color = "#e91e63") => ({ background: color + "18", color, fontSize: "12px", padding: "4px 12px", borderRadius: "20px", fontWeight: "500" }),

  // Cards
  card: { background: "#fff", borderRadius: "14px", padding: "20px 24px", boxShadow: "0 2px 12px rgba(233,30,99,0.06)", border: "1px solid #fce4ec", marginBottom: "16px" },
  statsGrid: { display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: "16px", marginBottom: "24px" },
  statCard: (color) => ({ background: "#fff", borderRadius: "14px", padding: "24px", textAlign: "center", boxShadow: "0 2px 12px rgba(0,0,0,0.05)", border: `1px solid ${color}22` }),
  statNum: (color) => ({ fontSize: "40px", fontWeight: "700", color, lineHeight: 1 }),
  statLabel: { fontSize: "13px", color: "#888", marginTop: "6px" },

  // Chat
  chatWrap: { display: "flex", height: "calc(100vh - 130px)", gap: "0" },
  userList: { width: "200px", background: "#fff", border: "1px solid #fce4ec", borderRadius: "14px 0 0 14px", overflowY: "auto", flexShrink: 0 },
  userListItem: (active) => ({
    display: "flex", alignItems: "center", gap: "10px",
    padding: "14px 16px", cursor: "pointer",
    background: active ? "#fce4ec" : "transparent",
    borderLeft: active ? "3px solid #e91e63" : "3px solid transparent",
    transition: "all 0.15s",
  }),
  chatMain: { flex: 1, display: "flex", flexDirection: "column", border: "1px solid #fce4ec", borderLeft: "none", borderRadius: "0 14px 14px 0", overflow: "hidden", background: "#fff" },
  chatHeader: { padding: "14px 20px", borderBottom: "1px solid #fce4ec", display: "flex", alignItems: "center", gap: "12px" },
  messages: { flex: 1, overflowY: "auto", padding: "20px", display: "flex", flexDirection: "column", gap: "10px", background: "#fafafa" },
  bubble: (mine) => ({
    maxWidth: "60%", padding: "10px 16px",
    borderRadius: mine ? "18px 18px 4px 18px" : "18px 18px 18px 4px",
    background: mine ? "#e91e63" : "#fff",
    color: mine ? "#fff" : "#333",
    alignSelf: mine ? "flex-end" : "flex-start",
    fontSize: "14px", lineHeight: "1.5",
    boxShadow: "0 1px 4px rgba(0,0,0,0.07)",
  }),
  timeLabel: (mine) => ({ fontSize: "10px", color: "#bbb", textAlign: mine ? "right" : "left", marginTop: "2px" }),
  inputRow: { display: "flex", gap: "10px", padding: "14px 16px", borderTop: "1px solid #fce4ec", background: "#fff" },
  input: { flex: 1, padding: "10px 16px", borderRadius: "24px", border: "1px solid #fce4ec", fontSize: "14px", outline: "none", background: "#fff5f7" },
  sendBtn: (disabled) => ({
    background: disabled ? "#fce4ec" : "#e91e63", color: disabled ? "#f48fb1" : "#fff",
    border: "none", borderRadius: "24px", padding: "10px 22px",
    cursor: disabled ? "not-allowed" : "pointer", fontSize: "14px", fontWeight: "600",
  }),

  // Feedback
  fbCard: { background: "#fff", borderRadius: "12px", padding: "18px 20px", border: "1px solid #fce4ec", marginBottom: "12px", boxShadow: "0 1px 6px rgba(233,30,99,0.05)" },
  anonBadge: { display: "inline-block", background: "#fce4ec", color: "#e91e63", fontSize: "11px", padding: "2px 10px", borderRadius: "20px", marginBottom: "8px", fontWeight: "500" },

  // Alerts
  alertCard: (sev) => ({
    background: "#fff", borderRadius: "12px", padding: "18px 20px", marginBottom: "12px",
    border: `1px solid ${sev === "HIGH" ? "#ffcdd2" : sev === "MEDIUM" ? "#fff9c4" : "#c8e6c9"}`,
  }),
  sevBadge: (sev) => ({
    display: "inline-block", fontSize: "11px", fontWeight: "600", padding: "2px 10px", borderRadius: "20px", marginLeft: "8px",
    background: sev === "HIGH" ? "#ffebee" : sev === "MEDIUM" ? "#fffde7" : "#e8f5e9",
    color: sev === "HIGH" ? "#c62828" : sev === "MEDIUM" ? "#f57f17" : "#2e7d32",
  }),
};

// =============================================
// CONSTANTS
// =============================================
const API = "http://localhost:8080/api";

// All users in the system
const USERS = [
  { name: "Alice", color: "#e91e63" },
  { name: "Bob",   color: "#9c27b0" },
  { name: "David", color: "#2196f3" },
  { name: "Eve",   color: "#009688" },
];

function getUser(name) {
  return USERS.find(u => u.name === name) || { name, color: "#aaa" };
}

// =============================================
// API HELPERS
// =============================================
async function apiGet(path) {
  const res = await fetch(API + path);
  if (!res.ok) throw new Error("API error");
  return res.json();
}

async function apiPost(path, body) {
  const res = await fetch(API + path, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!res.ok) throw new Error("API error");
  return res.json();
}

function timeStr(ts) {
  if (!ts) return "";
  const d = new Date(ts);
  return d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

// =============================================
// LOGIN SCREEN
// =============================================
function LoginScreen({ onLogin }) {
  const [selected, setSelected] = useState(null);

  return (
    <div style={S.loginWrap}>
      <div style={S.loginBox}>
        <div style={S.loginTitle}>🔐 PrivyNet</div>
        <div style={S.loginSub}>Secure Enterprise Communication</div>
        <div style={{ fontSize: "13px", color: "#aaa", marginBottom: "18px" }}>Choose your account to continue</div>

        <div style={S.userGrid}>
          {USERS.map(u => (
            <div
              key={u.name}
              style={S.userCard(selected === u.name)}
              onClick={() => setSelected(u.name)}
            >
              <div style={S.avatar(u.color)}>
                {u.name[0]}
              </div>
              <div style={{ fontSize: "14px", fontWeight: "600", color: "#333" }}>{u.name}</div>
              <div style={{ fontSize: "11px", color: "#aaa" }}>Employee</div>
            </div>
          ))}
        </div>

        <button
          style={S.loginBtn(!selected)}
          disabled={!selected}
          onClick={() => selected && onLogin(selected)}
        >
          {selected ? `Sign in as ${selected}` : "Select an account"}
        </button>

        <div style={{ fontSize: "11px", color: "#ccc", marginTop: "16px" }}>
          All communications are AES encrypted
        </div>
      </div>
    </div>
  );
}

// =============================================
// SIDEBAR
// =============================================
function Sidebar({ active, setActive, me, onLogout }) {
  const u = getUser(me);
  const tabs = [
    { id: "dashboard", label: "Dashboard",          icon: "⊞" },
    { id: "chat",      label: "Private Chat",        icon: "💬" },
    { id: "feedback",  label: "Express / Feedback",  icon: "📢" },
    { id: "alerts",    label: "Security Alerts",     icon: "🔔" },
  ];

  return (
    <div style={S.sidebar}>
      <div style={S.logo}>
        PrivyNet
        <span style={S.logoSub}>Secure Enterprise Comm</span>
      </div>

      {tabs.map(t => (
        <div key={t.id} style={S.navItem(active === t.id)} onClick={() => setActive(t.id)}>
          <span style={{ fontSize: "16px", width: "20px", textAlign: "center" }}>{t.icon}</span>
          {t.label}
        </div>
      ))}

      {/* Current user + logout */}
      <div style={S.userPill}>
        <div style={S.avatar(u.color, 30)}>{me[0]}</div>
        <div style={{ flex: 1 }}>
          <div style={{ fontSize: "13px", fontWeight: "600", color: "#333" }}>{me}</div>
          <div style={{ fontSize: "11px", color: "#4caf50" }}>● Online</div>
        </div>
        <button
          onClick={onLogout}
          style={{ background: "none", border: "none", cursor: "pointer", fontSize: "14px", color: "#f48fb1" }}
          title="Log out"
        >
          ⏏
        </button>
      </div>
    </div>
  );
}

// =============================================
// DASHBOARD
// =============================================
function Dashboard({ me }) {
  const [counts, setCounts] = useState({ messages: "…", feedback: "…", alerts: "…" });

  useEffect(() => {
    Promise.all([
      apiGet("/messages/count"),
      apiGet("/feedback/count"),
      apiGet("/alerts/count"),
    ]).then(([m, f, a]) => {
      setCounts({ messages: m.count ?? 0, feedback: f.count ?? 0, alerts: a.count ?? 0 });
    }).catch(() => setCounts({ messages: "–", feedback: "–", alerts: "–" }));
  }, []);

  return (
    <div>
      <p style={{ color: "#888", fontSize: "14px", marginBottom: "24px" }}>
        Welcome back, <strong style={{ color: "#e91e63" }}>{me}</strong>. Here's your activity overview.
      </p>

      <div style={S.statsGrid}>
        <div style={S.statCard("#e91e63")}>
          <div style={S.statNum("#e91e63")}>{counts.messages}</div>
          <div style={S.statLabel}>Total Messages</div>
        </div>
        <div style={S.statCard("#9c27b0")}>
          <div style={S.statNum("#9c27b0")}>{counts.feedback}</div>
          <div style={S.statLabel}>Feedback Posts</div>
        </div>
        <div style={S.statCard("#f44336")}>
          <div style={S.statNum("#f44336")}>{counts.alerts}</div>
          <div style={S.statLabel}>Security Alerts</div>
        </div>
      </div>

      <div style={S.card}>
        <h3 style={{ fontSize: "15px", fontWeight: "600", marginBottom: "8px", color: "#333" }}>🔒 Security Status</h3>
        <p style={{ fontSize: "14px", color: "#666", lineHeight: "1.7" }}>
          All messages are encrypted with <strong>AES-128</strong> before being stored.
          RSA key exchange is active. Your session is secure, {me}.
        </p>
      </div>

      <div style={S.card}>
        <h3 style={{ fontSize: "15px", fontWeight: "600", marginBottom: "10px", color: "#333" }}>👥 Active Users</h3>
        <div style={{ display: "flex", gap: "12px", flexWrap: "wrap" }}>
          {USERS.map(u => (
            <div key={u.name} style={{ display: "flex", alignItems: "center", gap: "8px", background: "#fff5f7", padding: "8px 14px", borderRadius: "30px", border: "1px solid #fce4ec" }}>
              <div style={{ width: "10px", height: "10px", borderRadius: "50%", background: "#4caf50" }} />
              <span style={{ fontSize: "13px", fontWeight: u.name === me ? "700" : "400", color: u.name === me ? "#e91e63" : "#555" }}>
                {u.name} {u.name === me ? "(you)" : ""}
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

// =============================================
// PRIVATE CHAT
// =============================================
function PrivateChat({ me }) {
  // Chat with the first "other" user by default
  const others = USERS.filter(u => u.name !== me);
  const [chatWith, setChatWith] = useState(others[0]?.name || "");
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [sending, setSending] = useState(false);
  const bottomRef = useRef(null);
  const pollRef = useRef(null);

  // Load messages whenever chatWith changes, and poll every 2 seconds
  useEffect(() => {
    if (!chatWith) return;

    loadMessages();

    // Clear old interval, set new one
    if (pollRef.current) clearInterval(pollRef.current);
    pollRef.current = setInterval(loadMessages, 2000);

    return () => clearInterval(pollRef.current);
  }, [chatWith, me]);

  // Auto-scroll to bottom when messages update
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  async function loadMessages() {
    try {
      const data = await apiGet(`/messages?user1=${me}&user2=${chatWith}`);
      setMessages(data);
    } catch {
      // backend offline — show nothing
    }
  }

  async function send() {
    if (!input.trim() || sending) return;
    setSending(true);
    try {
      await apiPost("/messages/send", {
        sender: me,
        receiver: chatWith,
        content: input.trim(),
      });
      setInput("");
      await loadMessages(); // refresh immediately after sending
    } catch {
      alert("Backend not running. Please start the Spring Boot server.");
    }
    setSending(false);
  }

  const partnerUser = getUser(chatWith);

  return (
    <div style={S.chatWrap}>
      {/* Left: user list */}
      <div style={S.userList}>
        <div style={{ padding: "14px 16px", borderBottom: "1px solid #fce4ec", fontSize: "12px", color: "#aaa", fontWeight: "600", textTransform: "uppercase", letterSpacing: "0.5px" }}>
          Contacts
        </div>
        {others.map(u => (
          <div
            key={u.name}
            style={S.userListItem(chatWith === u.name)}
            onClick={() => setChatWith(u.name)}
          >
            <div style={S.avatar(u.color, 32)}>{u.name[0]}</div>
            <div>
              <div style={{ fontSize: "13px", fontWeight: "600", color: "#333" }}>{u.name}</div>
              <div style={{ fontSize: "11px", color: "#4caf50" }}>● Online</div>
            </div>
          </div>
        ))}
      </div>

      {/* Right: chat window */}
      <div style={S.chatMain}>
        {/* Chat header */}
        <div style={S.chatHeader}>
          <div style={S.avatar(partnerUser.color, 36)}>{chatWith[0]}</div>
          <div>
            <div style={{ fontWeight: "600", fontSize: "15px", color: "#222" }}>{chatWith}</div>
            <div style={{ fontSize: "12px", color: "#4caf50" }}>🔐 End-to-end encrypted</div>
          </div>
          <div style={{ marginLeft: "auto", fontSize: "12px", color: "#bbb" }}>
            {messages.length} messages
          </div>
        </div>

        {/* Messages */}
        <div style={S.messages}>
          {messages.length === 0 && (
            <div style={{ textAlign: "center", color: "#ccc", marginTop: "60px", fontSize: "14px" }}>
              No messages yet. Say hi to {chatWith}! 👋
            </div>
          )}

          {messages.map(msg => {
            const mine = msg.sender === me;
            const senderUser = getUser(msg.sender);
            return (
              <div key={msg.id} style={{ alignSelf: mine ? "flex-end" : "flex-start", maxWidth: "65%" }}>
                {/* Show sender name only for received messages */}
                {!mine && (
                  <div style={{ fontSize: "11px", color: senderUser.color, marginBottom: "3px", paddingLeft: "4px", fontWeight: "600" }}>
                    {msg.sender}
                  </div>
                )}
                <div style={S.bubble(mine)}>{msg.content}</div>
                <div style={S.timeLabel(mine)}>{timeStr(msg.timestamp)}</div>
              </div>
            );
          })}

          <div ref={bottomRef} />
        </div>

        {/* Input */}
        <div style={S.inputRow}>
          <input
            style={S.input}
            type="text"
            placeholder={`Message ${chatWith}...`}
            value={input}
            onChange={e => setInput(e.target.value)}
            onKeyDown={e => e.key === "Enter" && !e.shiftKey && send()}
          />
          <button style={S.sendBtn(!input.trim() || sending)} onClick={send} disabled={!input.trim() || sending}>
            {sending ? "..." : "Send 🔐"}
          </button>
        </div>
      </div>
    </div>
  );
}

// =============================================
// FEEDBACK TAB
// =============================================
function FeedbackTab() {
  const [feedbacks, setFeedbacks] = useState([]);
  const [input, setInput] = useState("");
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    load();
    const iv = setInterval(load, 5000); // poll every 5s
    return () => clearInterval(iv);
  }, []);

  async function load() {
    try {
      const data = await apiGet("/feedback");
      setFeedbacks(data);
    } catch { /* backend offline */ }
  }

  async function submit() {
    if (!input.trim()) return;
    setSubmitting(true);
    try {
      await apiPost("/feedback/submit", { content: input.trim() });
      setInput("");
      await load();
    } catch {
      alert("Backend not running.");
    }
    setSubmitting(false);
  }

  return (
    <div>
      <div style={S.card}>
        <h3 style={{ fontSize: "15px", fontWeight: "600", marginBottom: "4px" }}>📢 Submit Anonymous Feedback</h3>
        <p style={{ fontSize: "13px", color: "#aaa", marginBottom: "14px" }}>Your identity is never recorded.</p>
        <textarea
          style={{ width: "100%", padding: "12px 16px", borderRadius: "10px", border: "1px solid #fce4ec", fontSize: "14px", outline: "none", resize: "vertical", minHeight: "90px", background: "#fff5f7", fontFamily: "inherit" }}
          placeholder="Share your thoughts anonymously..."
          value={input}
          onChange={e => setInput(e.target.value)}
        />
        <button
          style={{ ...S.sendBtn(!input.trim() || submitting), marginTop: "12px", borderRadius: "10px", padding: "10px 24px" }}
          onClick={submit}
          disabled={!input.trim() || submitting}
        >
          {submitting ? "Submitting..." : "Submit Anonymously"}
        </button>
      </div>

      <h3 style={{ fontSize: "15px", fontWeight: "600", color: "#444", marginBottom: "14px" }}>
        Community Feedback ({feedbacks.length})
      </h3>

      {feedbacks.length === 0 && (
        <div style={{ textAlign: "center", color: "#ccc", padding: "40px", fontSize: "14px" }}>
          No feedback yet. Be the first!
        </div>
      )}

      {[...feedbacks].reverse().map(fb => (
        <div key={fb.id} style={S.fbCard}>
          <span style={S.anonBadge}>Anonymous</span>
          <p style={{ fontSize: "14px", color: "#333", lineHeight: "1.6" }}>{fb.content}</p>
          <p style={{ fontSize: "11px", color: "#bbb", marginTop: "8px" }}>
            {fb.timestamp ? new Date(fb.timestamp).toLocaleString() : "Just now"}
          </p>
        </div>
      ))}
    </div>
  );
}

// =============================================
// SECURITY ALERTS TAB
// =============================================
function SecurityAlerts() {
  const [alerts, setAlerts] = useState([]);

  useEffect(() => {
    apiGet("/alerts").then(setAlerts).catch(() => {});
  }, []);

  const icons = { HIGH: "🔴", MEDIUM: "🟡", LOW: "🟢" };

  return (
    <div>
      <p style={{ fontSize: "14px", color: "#888", marginBottom: "20px" }}>
        {alerts.length} security event{alerts.length !== 1 ? "s" : ""} detected.
      </p>
      {alerts.map(a => (
        <div key={a.id} style={S.alertCard(a.severity)}>
          <div style={{ display: "flex", alignItems: "center", marginBottom: "8px" }}>
            <span style={{ fontSize: "16px" }}>{icons[a.severity] || "⚪"}</span>
            <strong style={{ fontSize: "14px", color: "#333", marginLeft: "8px" }}>
              {a.type?.replace(/_/g, " ")}
            </strong>
            <span style={S.sevBadge(a.severity)}>{a.severity}</span>
          </div>
          <p style={{ fontSize: "14px", color: "#555", lineHeight: "1.6" }}>{a.description}</p>
          <p style={{ fontSize: "11px", color: "#bbb", marginTop: "8px" }}>
            {a.timestamp ? new Date(a.timestamp).toLocaleString() : ""}
          </p>
        </div>
      ))}
    </div>
  );
}

// =============================================
// ROOT APP
// =============================================
const TAB_META = {
  dashboard: { title: "Dashboard",         badge: "Overview" },
  chat:      { title: "Private Chat",       badge: "AES Encrypted" },
  feedback:  { title: "Express / Feedback", badge: "Anonymous" },
  alerts:    { title: "Security Alerts",    badge: "Monitoring" },
};

export default function App() {
  // me = logged-in username, null = show login screen
  const [me, setMe] = useState(null);
  const [tab, setTab] = useState("dashboard");

  function login(name) {
    setMe(name);
    setTab("dashboard");
  }

  function logout() {
    setMe(null);
    setTab("dashboard");
  }

  // Show login screen if not logged in
  if (!me) return <LoginScreen onLogin={login} />;

  const meta = TAB_META[tab];

  return (
    <div style={S.app}>
      <Sidebar active={tab} setActive={setTab} me={me} onLogout={logout} />
      <div style={S.main}>
        <div style={S.header}>
          <span style={S.headerTitle}>{meta.title}</span>
          <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
            <span style={S.badge("#e91e63")}>{meta.badge}</span>
            <span style={{ fontSize: "13px", color: "#aaa" }}>Logged in as <strong style={{ color: "#e91e63" }}>{me}</strong></span>
          </div>
        </div>
        <div style={S.content}>
          {tab === "dashboard" && <Dashboard me={me} />}
          {tab === "chat"      && <PrivateChat me={me} />}
          {tab === "feedback"  && <FeedbackTab />}
          {tab === "alerts"    && <SecurityAlerts />}
        </div>
      </div>
    </div>
  );
}
